changeSet.sql:
CREATE UNIQUE INDEX IF NOT EXISTS idx_subscription_watchlist_user
    ON subscription (watchlist_id, user_id);

CREATE INDEX IF NOT EXISTS idx_subscription_user_id
    ON subscription (user_id);

CREATE INDEX IF NOT EXISTS idx_subscription_watchlist_id
    ON subscription (watchlist_id);

COMMENT ON TABLE subscription IS 'Stores user subscriptions to watchlists for severity-based notifications';
COMMENT ON COLUMN subscription.id IS 'Unique identifier for the subscription';
COMMENT ON COLUMN subscription.user_id IS 'Reference to the subscribing user';
COMMENT ON COLUMN subscription.watchlist_id IS 'Reference to the watchlist being subscribed to';
COMMENT ON COLUMN subscription.target_severities IS 'JSON array of severity levels to notify on (e.g. ["CRITICAL","WARNING"])';
COMMENT ON COLUMN subscription.adapters IS 'JSON array of notification adapters (e.g. ["IN_APP"])';
COMMENT ON COLUMN subscription.created_at IS 'Timestamp when the subscription was created';
COMMENT ON COLUMN subscription.updated_at IS 'Timestamp when the subscription was last updated';
COMMENT ON INDEX idx_subscription_watchlist_user IS 'Unique index ensuring one subscription per user per watchlist';
COMMENT ON INDEX idx_subscription_user_id IS 'Index for finding subscriptions by user';
COMMENT ON INDEX idx_subscription_watchlist_id IS 'Index for finding subscriptions by watchlist';

ALTER TABLE channel
    ADD COLUMN IF NOT EXISTS current_severity VARCHAR(20),
    ADD COLUMN IF NOT EXISTS last_notified_severity VARCHAR(20);
